import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root'
})
export class CommonService {
  baseUrl = environment.baseURL;
  constructor(private httpClient: HttpClient) { }

  tripDetailsSearchList(obj): Observable<any> {
    const url = this.baseUrl + 'tripDetails/search';
    return this.httpClient.post(url, obj);
  }

  tripDetailAddSubmit(requestObj): Observable<any> {
    const url = this.baseUrl + 'tripDetails/add';
    return this.httpClient.post(url, requestObj);
  }
  tripDetailModification(requestObj): Observable<any> {
    const url = this.baseUrl + 'tripDetails/update';
    return this.httpClient.put(url, requestObj);
  }
  activeVechicle(): Observable<any> {
    const url = this.baseUrl + 'vehicleDetails/active';
    return this.httpClient.get(url);
  }
  activeDriver(): Observable<any> {
    const url = this.baseUrl + 'DriverDetails/active';
    return this.httpClient.get(url);
  }
  getStatingKM(vehicleNumber): Observable<any> {
    const url = this.baseUrl + 'tripDetails/getLastRecordByV/' + vehicleNumber;
    return this.httpClient.get(url);
  }
  getTripDetails(tripId): Observable<any> {
    const url = this.baseUrl + 'tripDetails/getById/' + tripId;
    return this.httpClient.get(url);
  }

  getTripDetailsForward(req: any): Observable<any> {
    const url = this.baseUrl + 'tripDetails/approval';
    return this.httpClient.put(url, req);
  }
  getTripDetailLogs(refNumber): Observable<any> {
    const url = this.baseUrl + 'tripDetails/getLogsByTripNo/' + refNumber;
    return this.httpClient.get(url);
  }
  driverPaymentSubmit(requestObj): Observable<any> {
    const url = this.baseUrl + 'DriverSalary/add';
    return this.httpClient.post(url, requestObj);
  }


  payoutBalanceHistory(requestObj): Observable<any> {
    const url = this.baseUrl + 'balance/getBalanceHistoryDetails';
    return this.httpClient.post(url, requestObj);
  }

  payoutBalance(): Observable<any> {
    const url = this.baseUrl + 'balance/getAllBalanceDetails';
    return this.httpClient.get(url);
  }

  driverPaymentList(obj): Observable<any> {
    const url = this.baseUrl + 'DriverSalary/search';
    return this.httpClient.post(url, obj);
  }
  driverPaymentview(viewId): Observable<any> {
    const url = this.baseUrl + 'DriverSalary/getById/' + viewId;
    return this.httpClient.get(url);
  }

  getTripPaymentPendingList(): Observable<any> {
    const url = this.baseUrl + 'tripDetails/getPendingList';
    return this.httpClient.get(url);
  }
  tripdetailsdashboardcount(fromDate: string, toDate: string): Observable<any> {
    const url = this.baseUrl + 'tripDetails/dashboard';
    const params = new HttpParams()
      .set('fromDate', fromDate)
      .set('toDate', toDate);

    return this.httpClient.post<any>(url, {}, { params });
  }

dashBoardCount(month:any,year:any): Observable<any>{
  const url=this.baseUrl+'tripDetails/getTotalDriverTripsAndSalary';
  const params = new HttpParams()
  .set('month', month)
  .set('year', year);
  return this.httpClient.get<any>(url, { params }); ;
}

getTotalVehicleTripsAndProfit(month:any,year:any): Observable<any>{
  const url=this.baseUrl+'tripDetails/getTotalVehicleTripsAndProfit';
  const params = new HttpParams()
  .set('month', month)
  .set('year', year);
  return this.httpClient.get<any>(url, { params }); ;
}


}